def compute(vars):
    receivables = vars["v1"]
    liabilities = vars["v2"]
    if liabilities == 0:
        return None
    ratio = receivables / liabilities
    return {
        "value": ratio,
        "trace": {
            "receivables": receivables,
            "liabilities": liabilities,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
